//! Federation verification types for WASM.
//!
//! Mirror types from `parolnet-relay::authority` for CBOR deserialization,
//! with verification implemented directly using `ed25519-dalek` and `sha2`.
//! This avoids pulling `parolnet-relay` (which depends on tokio/transport)
//! into the WASM build.

use ed25519_dalek::{Signature, Verifier, VerifyingKey};
use parolnet_protocol::address::PeerId;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

// Generated by build.rs: AUTHORITY_PUBKEYS and AUTHORITY_THRESHOLD constants.
include!(concat!(env!("OUT_DIR"), "/trust_roots_generated.rs"));

/// Compute the network identity: SHA-256 of sorted authority pubkeys.
pub fn network_id() -> [u8; 32] {
    let mut sorted = AUTHORITY_PUBKEYS.to_vec();
    sorted.sort();
    let mut hasher = Sha256::new();
    for key in &sorted {
        hasher.update(key);
    }
    hasher.finalize().into()
}

/// Serde helper for `[u8; 64]` arrays (signatures).
mod sig_bytes {
    use serde::{Deserialize, Deserializer, Serialize, Serializer};

    pub fn serialize<S: Serializer>(bytes: &[u8; 64], serializer: S) -> Result<S::Ok, S::Error> {
        serde_bytes::Bytes::new(bytes.as_slice()).serialize(serializer)
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(deserializer: D) -> Result<[u8; 64], D::Error> {
        let v: Vec<u8> = serde_bytes::ByteBuf::deserialize(deserializer)?.into_vec();
        v.try_into().map_err(|v: Vec<u8>| {
            serde::de::Error::custom(format!("expected 64 bytes, got {}", v.len()))
        })
    }
}

/// A single authority's endorsement of one relay descriptor (mirror of
/// `parolnet_relay::authority::AuthorityEndorsement`). The signature covers
/// the whole descriptor, the relay's own signature included
/// (PNP-008-MUST-002).
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct AuthorityEndorsement {
    pub authority_pubkey: [u8; 32],
    #[serde(with = "sig_bytes")]
    pub signature: [u8; 64],
}

/// A signed relay descriptor (mirror of `parolnet_relay::directory::RelayDescriptor`).
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct RelayDescriptor {
    pub peer_id: PeerId,
    pub identity_key: [u8; 32],
    pub x25519_key: [u8; 32],
    pub addr: std::net::SocketAddr,
    pub bandwidth_class: u8,
    pub uptime_secs: u64,
    pub timestamp: u64,
    #[serde(with = "sig_bytes")]
    pub signature: [u8; 64],
    pub bandwidth_estimate: u64,
    pub next_pubkey: Option<[u8; 32]>,
}

/// A relay descriptor with authority endorsements (mirror of `parolnet_relay::authority::EndorsedDescriptor`).
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct EndorsedDescriptor {
    pub descriptor: RelayDescriptor,
    pub endorsements: Vec<AuthorityEndorsement>,
}

/// A complete signed directory snapshot from an authority (mirror of `parolnet_relay::authority::SignedDirectory`).
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SignedDirectory {
    pub descriptors: Vec<EndorsedDescriptor>,
    pub timestamp: u64,
    pub authority_pubkey: [u8; 32],
    #[serde(with = "sig_bytes")]
    pub signature: [u8; 64],
}

/// Helper for CBOR-serializable directory content (without signature).
#[derive(Serialize)]
struct DirectorySignableContent<'a> {
    descriptors: &'a Vec<EndorsedDescriptor>,
    timestamp: u64,
}

impl AuthorityEndorsement {
    /// Whether this is `authority_pubkey`'s signature over `descriptor`
    /// (PNP-008-MUST-002).
    pub fn verify(&self, descriptor: &RelayDescriptor) -> Result<bool, String> {
        let verifying_key = VerifyingKey::from_bytes(&self.authority_pubkey)
            .map_err(|e| format!("invalid authority pubkey: {e}"))?;
        let signature = Signature::from_bytes(&self.signature);
        Ok(verifying_key
            .verify(&descriptor.endorsement_signable_bytes(), &signature)
            .is_ok())
    }
}

/// PNP-008-MUST-027 item 3: a descriptor older than this is rejected.
pub const MAX_ENDORSED_DESCRIPTOR_AGE_SECS: u64 = 7 * 86400;

impl RelayDescriptor {
    /// The bytes the relay signs (mirror of
    /// `parolnet_relay::directory::RelayDescriptor::signable_bytes`).
    pub fn signable_bytes(&self) -> Vec<u8> {
        let mut buf = Vec::with_capacity(128);
        buf.extend_from_slice(&self.peer_id.0);
        buf.extend_from_slice(&self.identity_key);
        buf.extend_from_slice(&self.x25519_key);
        match self.addr {
            std::net::SocketAddr::V4(a) => {
                buf.push(4);
                buf.extend_from_slice(&a.ip().octets());
            }
            std::net::SocketAddr::V6(a) => {
                buf.push(6);
                buf.extend_from_slice(&a.ip().octets());
            }
        }
        buf.extend_from_slice(&self.addr.port().to_be_bytes());
        buf.push(self.bandwidth_class);
        buf.extend_from_slice(&self.uptime_secs.to_be_bytes());
        buf.extend_from_slice(&self.timestamp.to_be_bytes());
        buf.extend_from_slice(&self.bandwidth_estimate.to_be_bytes());
        if let Some(ref next_key) = self.next_pubkey {
            buf.push(1);
            buf.extend_from_slice(next_key);
        } else {
            buf.push(0);
        }
        buf
    }

    /// The bytes an authority signs to endorse this descriptor
    /// (PNP-008-MUST-002): its deterministic CBOR encoding, the relay's own
    /// signature included (mirror of
    /// `parolnet_relay::directory::RelayDescriptor::endorsement_signable_bytes`).
    pub fn endorsement_signable_bytes(&self) -> Vec<u8> {
        parolnet_protocol::det_cbor::to_deterministic_cbor(self)
            .expect("a relay descriptor always encodes as CBOR")
    }

    /// Whether this descriptor is its relay's own statement (PNP-008-MUST-027
    /// item 1): `peer_id` is the hash of `identity_key`, and `signature` is that
    /// key's over [`Self::signable_bytes`].
    pub fn verify_self_signature(&self) -> bool {
        if PeerId::from_public_key(&self.identity_key) != self.peer_id {
            return false;
        }
        let Ok(verifying_key) = VerifyingKey::from_bytes(&self.identity_key) else {
            return false;
        };
        verifying_key
            .verify(
                &self.signable_bytes(),
                &Signature::from_bytes(&self.signature),
            )
            .is_ok()
    }
}

impl EndorsedDescriptor {
    /// Validate the descriptor (PNP-008-MUST-027: its relay's signature by the
    /// key its PeerId is the hash of, and its age) and check that at least
    /// `threshold` distinct authorities of the trusted set signed this very
    /// descriptor (PNP-008-MUST-002).
    pub fn verify_threshold(
        &self,
        authority_pubkeys: &[[u8; 32]],
        threshold: usize,
        now_secs: u64,
    ) -> Result<bool, String> {
        if now_secs.saturating_sub(self.descriptor.timestamp) >= MAX_ENDORSED_DESCRIPTOR_AGE_SECS {
            return Ok(false);
        }
        if !self.descriptor.verify_self_signature() {
            return Ok(false);
        }

        let mut valid_authorities: Vec<[u8; 32]> = Vec::new();

        for endorsement in &self.endorsements {
            if !authority_pubkeys.contains(&endorsement.authority_pubkey) {
                continue;
            }
            if !endorsement.verify(&self.descriptor)? {
                continue;
            }
            if !valid_authorities.contains(&endorsement.authority_pubkey) {
                valid_authorities.push(endorsement.authority_pubkey);
            }
        }

        Ok(valid_authorities.len() >= threshold)
    }
}

impl SignedDirectory {
    /// SHA-256 hash of CBOR-encoded (descriptors + timestamp).
    pub fn signable_bytes(&self) -> Vec<u8> {
        let content = DirectorySignableContent {
            descriptors: &self.descriptors,
            timestamp: self.timestamp,
        };
        let mut cbor_buf = Vec::new();
        ciborium::into_writer(&content, &mut cbor_buf)
            .expect("CBOR serialization should not fail for valid data");
        let mut hasher = Sha256::new();
        hasher.update(&cbor_buf);
        hasher.finalize().to_vec()
    }

    /// Verify the signing authority is in the trusted set and signature is valid.
    pub fn verify(&self, authority_pubkeys: &[[u8; 32]]) -> Result<bool, String> {
        if !authority_pubkeys.contains(&self.authority_pubkey) {
            return Ok(false);
        }

        let verifying_key = VerifyingKey::from_bytes(&self.authority_pubkey)
            .map_err(|e| format!("invalid authority pubkey: {e}"))?;
        let signature = Signature::from_bytes(&self.signature);
        let signable = self.signable_bytes();
        Ok(verifying_key.verify(&signable, &signature).is_ok())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use ed25519_dalek::{Signer, SigningKey};

    fn descriptor(relay: &SigningKey, addr: &str, timestamp: u64) -> RelayDescriptor {
        let identity_key = relay.verifying_key().to_bytes();
        let mut d = RelayDescriptor {
            peer_id: PeerId::from_public_key(&identity_key),
            identity_key,
            x25519_key: [0xBB; 32],
            addr: addr.parse().unwrap(),
            bandwidth_class: 1,
            uptime_secs: 3600,
            timestamp,
            signature: [0u8; 64],
            bandwidth_estimate: 1000,
            next_pubkey: None,
        };
        d.signature = relay.sign(&d.signable_bytes()).to_bytes();
        d
    }

    /// An endorsement is for one descriptor (PNP-008-MUST-002); it must not carry
    /// over to a descriptor with other keys or another address (PNP-008-MUST-027).
    #[test]
    fn endorsement_does_not_carry_to_another_descriptor() {
        let authority = SigningKey::from_bytes(&[1; 32]);
        let trusted = [authority.verifying_key().to_bytes()];
        let relay = SigningKey::from_bytes(&[7; 32]);
        let attacker = SigningKey::from_bytes(&[66; 32]);
        let now = 1_800_000_000;

        let genuine = descriptor(&relay, "198.51.100.7:443", now);
        let endorse = |d: &RelayDescriptor| AuthorityEndorsement {
            authority_pubkey: trusted[0],
            signature: authority.sign(&d.endorsement_signable_bytes()).to_bytes(),
        };
        let endorsement = endorse(&genuine);
        let accepted = |descriptor: RelayDescriptor, at: u64| {
            EndorsedDescriptor {
                descriptor,
                endorsements: vec![endorsement.clone()],
            }
            .verify_threshold(&trusted, 1, at)
            .unwrap()
        };
        assert!(accepted(genuine.clone(), now));

        let mut forged = descriptor(&attacker, "203.0.113.66:443", now);
        forged.peer_id = genuine.peer_id;
        forged.signature = attacker.sign(&forged.signable_bytes()).to_bytes();
        assert!(!accepted(forged, now));

        let mut moved = genuine.clone();
        moved.addr = "203.0.113.66:443".parse().unwrap();
        assert!(!accepted(moved, now));

        // The relay's own, validly signed descriptor at another address: the
        // endorsement was not made for it.
        let relocated = descriptor(&relay, "203.0.113.66:443", now);
        assert!(relocated.verify_self_signature());
        assert!(!accepted(relocated, now));

        // MUST-027 item 3: older than seven days, even when endorsed as such.
        let old = descriptor(&relay, "198.51.100.7:443", now - 7 * 86400);
        let old = EndorsedDescriptor {
            endorsements: vec![endorse(&old)],
            descriptor: old,
        };
        assert!(!old.verify_threshold(&trusted, 1, now).unwrap());
    }

    /// The native relay crate and this mirror sign and verify the same bytes:
    /// the encoding does not depend on either crate's field order.
    #[test]
    fn endorsement_bytes_are_the_deterministic_cbor_of_the_descriptor() {
        let relay = SigningKey::from_bytes(&[7; 32]);
        let d = descriptor(&relay, "198.51.100.7:443", 1_800_000_000);
        let bytes = d.endorsement_signable_bytes();
        let back: RelayDescriptor = ciborium::from_reader(bytes.as_slice()).unwrap();
        assert_eq!(back.endorsement_signable_bytes(), bytes);
        // A map of the ten descriptor fields, shortest key first.
        assert_eq!(bytes[0], 0xaa);
        assert_eq!(&bytes[1..6], b"\x64addr");
    }
}
